<template>
  <section class="factory" v-loading="loading">
    <div class="intro"><div><div class="eyebrow">FORGEPILOT / INTEGRATION CENTER</div><h1>连接器工厂</h1><p>统一接入契约与字段语义，让数据进入 ForgePilot 的业务管理闭环。</p></div><div class="actions"><el-button @click="reload" :disabled="dirty">刷新</el-button><el-button v-if="canWrite" @click="initialize" :loading="busy">补齐初始化配置</el-button></div></div>
    <div class="stats"><div><strong>{{ connectors.length }}</strong><span>已配置数据源契约</span></div><div><strong>{{ totalFields }}</strong><span>字段映射契约</span></div><div><strong>{{ configuredFields }}</strong><span>已定义源路径</span></div><div><strong>{{ totalFields-configuredFields }}</strong><span>待源字段确认</span></div></div>
    <div class="data-flow" aria-label="工业数据流"><span>数据源接入契约</span><b>→</b><span>字段映射与校验</span><b>→</b><span>本体数字底座</span><b>→</b><strong>ForgePilot 管理</strong><b>→</b><span>可视化 / 链上管理</span></div>
    <p class="scope">当前维护只读接入契约。配置校验、样本检查与实际连接分开记录；业务调度与上链仍在 ForgePilot 执行。</p>
    <el-tabs v-model="tab">
      <el-tab-pane label="数据源与字段映射" name="sources">
        <div class="workspace">
          <aside class="source-list"><div class="list-caption">工业数据源 <small>{{ connectors.length }}</small></div><button v-for="ds in connectors" :key="ds.code" class="source-item" :class="{selected: current?.code===ds.code}" @click="select(ds)"><span class="source-code">{{ ds.code }}</span><strong>{{ ds.name }}</strong><span>{{ ds.systems }}</span><div class="source-state"><i :class="{defined:ds.demo}"></i>{{ ds.demo ? '演示适配定义' : '待接入 · 契约草稿' }}<small>v{{ ds.version }}</small></div></button></aside>
          <div v-if="current" class="source-detail">
            <div class="detail-heading"><div><h2>{{ current.name }}</h2><p>{{ current.description }}</p></div><el-tag :type="current.contractValidated?'success':'info'" effect="plain">{{ current.contractValidated ? '配置契约已校验' : '配置草稿' }}</el-tag></div>
            <div class="version-line"><span>{{ current.code }} · v{{ current.version }} · {{ current.updatedBy }} · {{ current.updatedAt?.replace('T',' ') + '（数据库时间）' }}</span><span v-if="dirty" class="dirty">有未保存修改</span><span>未测试实际连接 · 未启用同步</span></div>
            <el-tabs v-model="detailTab">
              <el-tab-pane label="接入配置" name="config">
                <el-form label-position="top" :disabled="!canWrite" class="config-grid">
                  <el-form-item label="数据源名称"><el-input v-model="current.name" maxlength="100"/></el-form-item>
                  <el-form-item label="接入协议"><el-select v-model="current.config.protocol"><el-option label="HTTP API 契约" value="HTTP_API"/><el-option label="MySQL 只读契约" value="JDBC_MYSQL"/><el-option label="JSON 文件契约" value="FILE_JSON"/></el-select></el-form-item>
                  <el-form-item class="full" label="端点 / 文件标识（不包含密码或查询参数）"><el-input v-model="current.config.endpoint" :placeholder="current.config.protocol==='JDBC_MYSQL'?'jdbc:mysql://主机:端口/库名':'填写已确认的接口地址或文件标识'"/><small>此地址仅保存为契约，不会从此页面发起远端请求。实际 MySQL 扫描使用「JDBC 扫描工作台」。</small></el-form-item>
                  <el-form-item label="凭据引用"><el-input v-model="current.config.credentialRef" placeholder="env:ERP_READ_TOKEN 或 vault:路径"/><small>仅保存引用，不收集密码、令牌，也不解析引用。</small></el-form-item>
                  <el-form-item label="租户 / 来源命名空间"><el-input v-model="current.config.namespace" placeholder="由数据负责人确认的稳定来源标识"/></el-form-item>
                  <el-form-item label="接入负责人"><el-input v-model="current.config.owner"/></el-form-item>
                  <el-form-item label="权限范围"><el-input v-model="current.config.permissionScope" placeholder="组织、角色与字段授权范围"/></el-form-item>
                  <el-form-item label="同步策略（计划）"><el-select v-model="current.config.syncMode"><el-option label="全量快照" value="SNAPSHOT"/><el-option label="水位增量" value="WATERMARK"/></el-select></el-form-item>
                  <el-form-item label="水位字段 / 游标"><el-input v-model="current.config.watermarkField" placeholder="增量模式必填，须由真实源字典确认"/></el-form-item>
                  <el-form-item label="调度间隔 / 分钟"><el-input-number v-model="current.config.cadenceMinutes" :min="1" :max="10080"/></el-form-item>
                  <el-form-item label="分页大小"><el-input-number v-model="current.config.pageSize" :min="1" :max="10000"/></el-form-item>
                  <el-form-item label="最大重试次数"><el-input-number v-model="current.config.maxRetries" :min="0" :max="10"/></el-form-item>
                  <el-form-item label="增量重叠窗口 / 秒"><el-input-number v-model="current.config.overlapSeconds" :min="0" :max="86400"/></el-form-item>
                  <el-form-item label="删除与撤回策略"><el-select v-model="current.config.deletionPolicy"><el-option label="显式墓碑 / 撤回记录" value="EXPLICIT_TOMBSTONE"/><el-option label="全量核对差异" value="FULL_RECONCILIATION"/></el-select></el-form-item>
                  <el-form-item label="记录身份规则"><el-input v-model="current.config.identityPolicy"/></el-form-item>
                  <el-form-item class="full" label="时间语义"><el-input v-model="current.config.timePolicy"/></el-form-item>
                  <el-form-item class="full" label="对账与异常处理要求"><el-input v-model="current.config.reconciliation"/></el-form-item>
                </el-form>
              </el-tab-pane>
              <el-tab-pane :label="`字段映射（${current.mappings.length}）`" name="mappings">
                <div class="mapping-toolbar"><el-select v-model="entityFilter" placeholder="全部对象" filterable @change="page=1"><el-option label="全部对象" value=""/><el-option v-for="e in entities" :key="e.code" :label="`${e.name} · ${e.code}`" :value="e.code"/></el-select><el-input v-model="search" clearable placeholder="搜索目标属性、源集合或字段" @input="page=1"/><span>{{ filtered.length }} 项 · {{ mappedCurrent }} 条源路径已定义</span></div>
                <p class="scope">生产模板中的源集合与字段保持空缺。这里只支持直接映射，类型与单位须匹配目标契约；空值保留 unknown，不补零。</p>
                <el-table :data="paged" :row-key="row=>`${row.entity}.${row.target}`" border size="small" class="mapping-table">
                  <el-table-column label="本体目标" min-width="210"><template #default="{row}"><strong>{{ row.entityName }} · {{ row.targetName }}</strong><code>{{ row.entity }}.{{ row.target }}</code><small class="target-spec">目标 {{ targetSpec(row) }}</small><el-tag v-if="row.key" size="small" effect="plain">身份</el-tag><el-tag v-else-if="row.required" size="small" type="warning" effect="plain">必填</el-tag></template></el-table-column>
                  <el-table-column label="源集合 / 表" min-width="160"><template #default="{row}"><el-input v-model="row.collection" :disabled="!canWrite" placeholder="待确认" maxlength="256"/></template></el-table-column>
                  <el-table-column label="源字段（精确键名）" min-width="160"><template #default="{row}"><el-input v-model="row.field" :disabled="!canWrite" placeholder="待确认" maxlength="256"/></template></el-table-column>
                  <el-table-column label="源类型" width="155"><template #default="{row}"><el-select v-model="row.type" :disabled="!canWrite"><el-option v-for="v in types" :key="v" :label="v" :value="v"/></el-select></template></el-table-column>
                  <el-table-column label="源单位" width="110"><template #default="{row}"><el-input v-model="row.unit" :disabled="!canWrite" placeholder="无" maxlength="32"/></template></el-table-column>
                  <el-table-column label="校验范围" width="115"><template #default="{row}"><el-tag :type="row.collection&&row.field?'success':'info'" size="small" effect="plain">{{ row.collection&&row.field?'路径已定义':'待源确认' }}</el-tag><el-checkbox v-model="row.enabled" :disabled="!canWrite || row.key || row.required">纳入</el-checkbox></template></el-table-column>
                </el-table>
                <el-pagination v-model:current-page="page" :page-size="15" layout="prev, pager, next, total" :total="filtered.length" class="pagination"/>
                <div class="contract-note">基线：{{ current.catalogRelease }}<br>身份规则：{{ current.config.identityPolicy }}；EvidenceVersion 需使用证据 ID + 版本号。集合中的冒号表示回执类型过滤，点号保留现有适配器定义，不视为物理 SQL 表名。</div>
              </el-tab-pane>
              <el-tab-pane label="校验与样本" name="validation">
                <el-alert :title="dirty?'先保存当前修改，再校验配置或样本。':'配置校验不会测试网络连通、解析凭据或发布映射。'" type="info" :closable="false"/>
                <div class="validation-panel"><el-button type="primary" :loading="busy" :disabled="!canWrite||dirty" @click="validate">校验已保存配置</el-button><span v-if="current.validation">v{{ current.validation.version }} · {{ current.validation.valid?'配置契约检查通过':'仍有待完善项' }} · {{ current.validation.errors }} 项错误</span></div>
                <p v-if="current.validation" class="scope">{{ current.validation.scope }}</p>
                <el-table v-if="current.validation" :data="current.validation.issues" max-height="280" size="small"><el-table-column prop="severity" label="级别" width="90"/><el-table-column prop="target" label="对象 / 配置" min-width="180"/><el-table-column prop="message" label="检查结果" min-width="250"/></el-table>
                <h3>源记录样本检查</h3><p class="scope">粘贴所选对象源集合的 JSON 数组，1–100 条。按精确源键名核对必填、类型和样本内身份；样本仅在请求中处理，不落库，不替代源系统验收。</p>
                <div class="mapping-toolbar"><el-select v-model="sampleEntity" filterable><el-option v-for="e in entities" :key="e.code" :label="`${e.name} · ${e.code}`" :value="e.code"/></el-select><el-button :disabled="!canWrite||dirty||!sampleEntity" :loading="busy" @click="checkSample">检查样本</el-button></div>
                <el-input v-model="sampleText" type="textarea" :rows="7" placeholder='[{"id":"源记录ID"}]' :disabled="!canWrite"/>
                <div v-if="sampleResult" class="sample-result"><p>{{ sampleResult.entity }} · {{ sampleResult.rows }} 条样本 · {{ sampleResult.errors }} 项错误 · {{ sampleResult.valid?'所列检查通过':'请修正后重试' }}</p><el-table :data="sampleResult.issues" max-height="260" size="small"><el-table-column prop="severity" label="级别" width="90"/><el-table-column prop="target" label="样本 / 目标" min-width="200"/><el-table-column prop="message" label="结果" min-width="250"/></el-table></div>
              </el-tab-pane>
              <el-tab-pane label="变更记录" name="logs"><div class="validation-panel"><el-button @click="loadLogs">刷新记录</el-button><span>最近 30 条配置变更与校验记录 · 不包含样本原始数据</span></div><el-table :data="logs" size="small"><el-table-column prop="operation" label="操作"/><el-table-column prop="version" label="版本" width="90"/><el-table-column prop="actor" label="操作人"/><el-table-column prop="at" label="时间（数据库）" min-width="200"/><el-table-column label="明细" width="90"><template #default="{row}"><el-button link @click="logDetail=JSON.stringify(row.detail,null,2);logVisible=true">查看</el-button></template></el-table-column></el-table></el-tab-pane>
            </el-tabs>
            <div class="save-bar"><span>所有配置与字段映射按同一版本保存 · 保存后需重新校验</span><el-button @click="exportConfig">导出配置</el-button><el-button v-if="canWrite" type="primary" :disabled="!dirty" :loading="busy" @click="save">保存配置与映射</el-button></div>
          </div>
          <el-empty v-else description="暂无连接器，请补齐初始化配置"/>
        </div>
      </el-tab-pane>
      <el-tab-pane label="连接器模板" name="templates"><div class="template-grid"><article v-for="tpl in templates" :key="tpl.code" class="template-card"><span class="source-code">{{ tpl.code }}</span><h2>{{ tpl.name }}</h2><p>{{ tpl.systems }}</p><p>{{ new Set(tpl.mappings.map(m=>m.entity)).size }} 类对象 · {{ tpl.mappings.length }} 条字段契约</p><small>{{ tpl.description }}</small><el-button v-if="canWrite" @click="newConnector(tpl)">从模板创建</el-button></article></div></el-tab-pane>
      <el-tab-pane label="JDBC 扫描工作台" name="jdbc" lazy><p class="scope">沿用已有 MySQL 连接、物理表扫描与映射生命周期。连接器工厂中的草稿不会自动写入生效映射。</p><JdbcWorkbench/></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="createVisible" title="从模板创建连接器" width="480px"><el-form label-position="top"><el-form-item label="模板"><el-input :model-value="createForm.templateCode" disabled/></el-form-item><el-form-item label="连接器编码（大写字母、数字、下划线）"><el-input v-model="createForm.code" maxlength="64" placeholder="例如 ERP_FACTORY_01"/></el-form-item><el-form-item label="连接器名称"><el-input v-model="createForm.name" maxlength="100"/></el-form-item></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="create">创建草稿</el-button></template></el-dialog>
    <el-dialog v-model="logVisible" title="配置版本 / 校验明细" width="75%"><el-input :model-value="logDetail" type="textarea" :rows="22" readonly/></el-dialog>
  </section>
</template>
<script setup>
import {ref,computed,onMounted,watch} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useUserStore} from '../../store/user'
import JdbcWorkbench from './JdbcWorkbench.vue'
import {connectorTemplates,connectorList,initializeConnectors,createConnector,saveConnector,validateConnector,sampleConnector,connectorLogs} from '../../api/connectorFactory'
const user=useUserStore(),canWrite=computed(()=>['ADMIN','EDITOR'].includes(user.user?.role))
const loading=ref(false),busy=ref(false),connectors=ref([]),templates=ref([]),current=ref(null),baseline=ref(''),tab=ref('sources'),detailTab=ref('config')
const entityFilter=ref(''),search=ref(''),page=ref(1),logs=ref([]),sampleEntity=ref(''),sampleText=ref(''),sampleResult=ref(null),createVisible=ref(false),logVisible=ref(false),logDetail=ref(''),createForm=ref({})
const types=['string','integer','boolean','date','datetime','date_or_datetime','enum','array','object']
const totalFields=computed(()=>connectors.value.reduce((n,d)=>n+d.mappings.length,0))
const configuredFields=computed(()=>connectors.value.reduce((n,d)=>n+d.mappings.filter(m=>m.collection&&m.field).length,0))
const dirty=computed(()=>current.value && JSON.stringify(current.value)!==baseline.value)
const mappedCurrent=computed(()=>current.value?.mappings.filter(m=>m.collection&&m.field).length||0)
const entities=computed(()=>Array.from(new Map((current.value?.mappings||[]).map(m=>[m.entity,{code:m.entity,name:m.entityName}])).values()))
const filtered=computed(()=>(current.value?.mappings||[]).filter(m=>(!entityFilter.value||m.entity===entityFilter.value)&&(!search.value||[m.entity,m.entityName,m.target,m.targetName,m.collection,m.field].join(' ').toLowerCase().includes(search.value.toLowerCase()))))
const paged=computed(()=>filtered.value.slice((page.value-1)*15,page.value*15))
function targetSpec(row){const base=templates.value.find(t=>t.code===current.value?.templateCode)?.mappings.find(m=>m.entity===row.entity&&m.target===row.target);return base?`${base.type}${base.unit?` / ${base.unit}`:''}`:''}
function useDocument(ds){if(!ds){current.value=null;baseline.value='';return}current.value=JSON.parse(JSON.stringify(ds));baseline.value=JSON.stringify(current.value);entityFilter.value='';search.value='';page.value=1;logs.value=[];sampleText.value='';sampleResult.value=null;sampleEntity.value=entities.value[0]?.code||''}
async function select(ds){if(current.value?.code===ds.code)return;if(dirty.value){try{await ElMessageBox.confirm('切换数据源会放弃未保存修改。','未保存修改',{confirmButtonText:'放弃并切换',cancelButtonText:'继续编辑',type:'warning'})}catch{return}}useDocument(ds);if(detailTab.value==='logs')await loadLogs()}
async function reload(){loading.value=true;try{const [ds,tpl]=await Promise.all([connectorList(),connectorTemplates()]);connectors.value=ds;templates.value=tpl;useDocument(ds.find(d=>d.code===current.value?.code)||ds.find(d=>d.code==='FP_DEMO')||ds[0])}finally{loading.value=false}}
async function initialize(){busy.value=true;try{const result=await initializeConnectors();ElMessage.success(`新增 ${result.created} 份，保留 ${result.preserved} 份已有配置`);if(!dirty.value)await reload()}finally{busy.value=false}}
function updateDocument(doc){connectors.value=connectors.value.map(d=>d.code===doc.code?doc:d);useDocument(doc)}
async function save(){busy.value=true;try{updateDocument(await saveConnector(current.value.code,current.value));ElMessage.success('配置与字段映射已按新版本保存')}finally{busy.value=false}}
async function validate(){busy.value=true;try{const doc=await validateConnector(current.value.code,current.value.version);updateDocument(doc);ElMessage[doc.contractValidated?'success':'warning'](doc.contractValidated?'配置契约检查通过；实际连接仍待验证':'存在待完善项，请查看检查结果')}finally{busy.value=false}}
async function checkSample(){let rows;try{rows=JSON.parse(sampleText.value)}catch{ElMessage.error('样本必须是有效 JSON 数组');return}busy.value=true;try{sampleResult.value=await sampleConnector(current.value.code,{version:current.value.version,entity:sampleEntity.value,rows})}finally{busy.value=false}}
async function loadLogs(){if(current.value)logs.value=await connectorLogs(current.value.code)}
watch(detailTab,v=>{if(v==='logs')loadLogs()})
function newConnector(tpl){if(dirty.value){ElMessage.warning('请先保存当前配置，再创建连接器');tab.value='sources';return}createForm.value={templateCode:tpl.code,code:'',name:tpl.name};createVisible.value=true}
async function create(){busy.value=true;try{const doc=await createConnector(createForm.value);createVisible.value=false;await reload();useDocument(doc);tab.value='sources';detailTab.value='config';ElMessage.success('已创建连接器草稿')}finally{busy.value=false}}
function exportConfig(){const blob=new Blob([JSON.stringify(current.value,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${current.value.code}-v${current.value.version}${dirty.value?'-unsaved':''}.json`;a.click();URL.revokeObjectURL(url)}
onMounted(reload)
</script>
<style scoped>
